    union {
        long long   int_val;
        double      float_val;
        char        char_val;
        char       *str_val;      /* 힙 할당 */
        char       *ident;        /* 힙 할당 */
    } val;
} Token;

/* Lexer 상태 */
typedef struct {
    const char *src;
    size_t      src_len;
    size_t      pos;        /* 현재 위치 */
    int         line;       /* 현재 줄 */
    int         col;        /* 현재 열 */

    Token      *tokens;     /* 동적 배열 */
    size_t      tok_count;
    size_t      tok_cap;
