TEST_SUITE_START("Lexer Test Suite")

RUN_TEST(keywords);
RUN_TEST(int_decimal);
RUN_TEST(int_hex);
RUN_TEST(int_octal);
RUN_TEST(identifier);
RUN_TEST(arithmetic_ops);
RUN_TEST(comparison_ops);
RUN_TEST(logical_ops);
RUN_TEST(assignment_ops);
