#include "parser.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

/* Parser 생성 */
Parser *parser_new(Lexer *lexer) {
    Parser *p = (Parser *)malloc(sizeof(Parser));
    if (!p) return NULL;

    p->lexer = lexer;
    p->current = 0;
    p->tokens = lexer->tokens;
    p->tok_count = lexer->tok_count;

    return p;
}

/* Parser 해제 */
void parser_free(Parser *p) {
    if (p) free(p);
}

/* 현재 토큰 */
Token *current_token(Parser *p) {
    if (p->current >= (int)p->tok_count) {
        return &p->tokens[p->tok_count - 1];  /* EOF */
    }
    return &p->tokens[p->current];
}

/* 앞의 토큰 */
Token *peek_token(Parser *p, int offset) {
    int idx = p->current + offset;
    if (idx >= (int)p->tok_count) {
        return &p->tokens[p->tok_count - 1];  /* EOF */
    }
    return &p->tokens[idx];
}

/* 한 토큰 진행 */
void advance(Parser *p) {
    if (p->current < (int)p->tok_count) {
        p->current++;
    }
}

/* 현재 토큰이 kind와 일치하는지 */
int check(Parser *p, TokenKind kind) {
    return current_token(p)->kind == kind;
}

/* 현재 토큰이 kind와 일치하면 진행하고 1 반환 */
int match(Parser *p, TokenKind kind) {
    if (check(p, kind)) {
        advance(p);
        return 1;
    }
    return 0;
}

/* 현재 토큰이 kind와 일치해야 함 (아니면 에러) */
int consume(Parser *p, TokenKind kind, const char *msg) {
    if (!check(p, kind)) {
        fprintf(stderr, "Parse error at line %d: %s (expected %d, got %d)\n",
                current_token(p)->loc.line, msg, kind, current_token(p)->kind);
        return 0;
    }
    advance(p);
    return 1;
}

/* 프로그램 파싱 */
Node *parse_program(Parser *p) {
    Token loc_tok = *current_token(p);
    Node *program = node_new(ND_PROGRAM, loc_tok.loc);

    while (!check(p, TK_EOF)) {
        if (match(p, TK_TYPEDEF)) {
            /* typedef 스킵 (Phase 3.4에서) */
            advance(p);
            continue;
        }

        Node *decl = parse_declaration(p);
        if (decl) {
            node_add_child(program, decl);
        }
    }

    return program;
}

/* 선언 파싱 */
Node *parse_declaration(Parser *p) {
    Token tok = *current_token(p);

    /* 함수 또는 변수 선언 */
    if (check(p, TK_INT) || check(p, TK_CHAR) || check(p, TK_FLOAT) ||
        check(p, TK_DOUBLE) || check(p, TK_VOID) || check(p, TK_LONG) ||
        check(p, TK_SHORT) || check(p, TK_UNSIGNED) || check(p, TK_SIGNED)) {

        /* 타입 파싱 */
        Node *type_node = parse_type(p);
        if (!type_node) return NULL;

        /* 식별자 파싱 */
        if (!check(p, TK_IDENT)) {
            fprintf(stderr, "Expected identifier at line %d\n", tok.loc.line);
            node_free_recursive(type_node);
            return NULL;
        }

        Token ident_tok = *current_token(p);
        char *ident = ident_tok.val.ident;
        advance(p);

        /* 함수 정의 vs 변수 선언 */
        if (check(p, TK_LPAREN)) {
            /* 함수 정의 */
            advance(p);  /* ( */

            Node *func_def = node_new(ND_FUNC_DEF, tok.loc);
            func_def->name = (char *)malloc(strlen(ident) + 1);
            strcpy(func_def->name, ident);
            func_def->type_node = type_node;

            /* 파라미터 리스트 */
            while (!check(p, TK_RPAREN)) {
                Node *param = parse_type(p);
                if (!param) break;

                if (check(p, TK_IDENT)) {
                    char *param_name = current_token(p)->val.ident;
                    param->name = (char *)malloc(strlen(param_name) + 1);
                    strcpy(param->name, param_name);
                    advance(p);
                }

                node_add_child(func_def, param);

                if (!match(p, TK_COMMA)) break;
            }

            consume(p, TK_RPAREN, "Expected )");

            /* 함수 본체 */
            if (check(p, TK_LBRACE)) {
                func_def->body = parse_block(p);
            } else if (!check(p, TK_SEMICOLON)) {
                fprintf(stderr, "Expected ; or { at line %d\n", current_token(p)->loc.line);
                node_free_recursive(func_def);
                return NULL;
            }

            if (check(p, TK_SEMICOLON)) advance(p);

            return func_def;
        } else {
            /* 변수 선언 */
            Node *var_decl = node_new(ND_VAR_DECL, tok.loc);
            var_decl->name = (char *)malloc(strlen(ident) + 1);
            strcpy(var_decl->name, ident);
            var_decl->type_node = type_node;

            /* 초기값 */
            if (match(p, TK_ASSIGN)) {
                var_decl->left = parse_assign_expr(p);
            }

            consume(p, TK_SEMICOLON, "Expected ;");

            return var_decl;
        }
    }

    fprintf(stderr, "Expected declaration at line %d\n", tok.loc.line);
    return NULL;
}

/* 타입 파싱 */
Node *parse_type(Parser *p) {
    Token tok = *current_token(p);
    Node *type_node = NULL;

    if (check(p, TK_INT)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(4);
        strcpy(type_node->name, "int");
        advance(p);
    } else if (check(p, TK_CHAR)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(5);
        strcpy(type_node->name, "char");
        advance(p);
    } else if (check(p, TK_FLOAT)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(6);
        strcpy(type_node->name, "float");
        advance(p);
    } else if (check(p, TK_DOUBLE)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(7);
        strcpy(type_node->name, "double");
        advance(p);
    } else if (check(p, TK_VOID)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(5);
        strcpy(type_node->name, "void");
        advance(p);
    } else if (check(p, TK_LONG)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(5);
        strcpy(type_node->name, "long");
        advance(p);
    } else if (check(p, TK_SHORT)) {
        type_node = node_new(ND_TYPE_BASE, tok.loc);
        type_node->name = (char *)malloc(6);
        strcpy(type_node->name, "short");
        advance(p);
    } else {
        return NULL;
    }

    /* 포인터 (Phase 3.1에서 완전 구현) */
    while (match(p, TK_STAR)) {
        Node *ptr_type = node_new(ND_TYPE_PTR, tok.loc);
        ptr_type->type_node = type_node;
        type_node = ptr_type;
    }

    return type_node;
}

/* 문장 파싱 */
Node *parse_statement(Parser *p) {
    Token tok = *current_token(p);

    if (check(p, TK_LBRACE)) {
        return parse_block(p);
    } else if (check(p, TK_IF)) {
        return parse_if_statement(p);
    } else if (check(p, TK_WHILE)) {
        return parse_while_statement(p);
    } else if (check(p, TK_DO)) {
        return parse_do_while_statement(p);
    } else if (check(p, TK_FOR)) {
        return parse_for_statement(p);
    } else if (check(p, TK_RETURN)) {
        return parse_return_statement(p);
    } else if (match(p, TK_BREAK)) {
        Node *break_stmt = node_new(ND_BREAK, tok.loc);
        consume(p, TK_SEMICOLON, "Expected ;");
        return break_stmt;
    } else if (match(p, TK_CONTINUE)) {
        Node *continue_stmt = node_new(ND_CONTINUE, tok.loc);
        consume(p, TK_SEMICOLON, "Expected ;");
        return continue_stmt;
    } else if (match(p, TK_SEMICOLON)) {
        return node_new(ND_NULL_STMT, tok.loc);
    } else {
        Node *expr = parse_expr(p);
        if (expr) {
            Node *expr_stmt = node_new(ND_EXPR_STMT, tok.loc);
            expr_stmt->left = expr;
            consume(p, TK_SEMICOLON, "Expected ;");
            return expr_stmt;
        }
        return NULL;
    }
}

/* 블록 파싱 */
Node *parse_block(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_LBRACE, "Expected {");

    Node *block = node_new(ND_BLOCK, tok.loc);

    while (!check(p, TK_RBRACE) && !check(p, TK_EOF)) {
        Node *stmt = parse_statement(p);
        if (stmt) {
            node_add_child(block, stmt);
        }
    }

    consume(p, TK_RBRACE, "Expected }");
    return block;
}

/* if 문 파싱 */
Node *parse_if_statement(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_IF, "Expected if");
    consume(p, TK_LPAREN, "Expected (");

    Node *if_stmt = node_new(ND_IF, tok.loc);
    if_stmt->cond = parse_expr(p);

    consume(p, TK_RPAREN, "Expected )");

    if_stmt->then_body = parse_statement(p);

    if (match(p, TK_ELSE)) {
        if_stmt->else_body = parse_statement(p);
    }

    return if_stmt;
}

/* while 문 파싱 */
Node *parse_while_statement(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_WHILE, "Expected while");
    consume(p, TK_LPAREN, "Expected (");

    Node *while_stmt = node_new(ND_WHILE, tok.loc);
    while_stmt->cond = parse_expr(p);

    consume(p, TK_RPAREN, "Expected )");

    while_stmt->body = parse_statement(p);

    return while_stmt;
}

/* do-while 문 파싱 */
Node *parse_do_while_statement(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_DO, "Expected do");

    Node *do_while = node_new(ND_DO_WHILE, tok.loc);
    do_while->body = parse_statement(p);

    consume(p, TK_WHILE, "Expected while");
    consume(p, TK_LPAREN, "Expected (");

    do_while->cond = parse_expr(p);

    consume(p, TK_RPAREN, "Expected )");
    consume(p, TK_SEMICOLON, "Expected ;");

    return do_while;
}

/* for 문 파싱 */
Node *parse_for_statement(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_FOR, "Expected for");
    consume(p, TK_LPAREN, "Expected (");

    Node *for_stmt = node_new(ND_FOR, tok.loc);

    if (!check(p, TK_SEMICOLON)) {
        for_stmt->init = parse_expr(p);
    }
    consume(p, TK_SEMICOLON, "Expected ;");

    if (!check(p, TK_SEMICOLON)) {
        for_stmt->cond = parse_expr(p);
    }
    consume(p, TK_SEMICOLON, "Expected ;");

    if (!check(p, TK_RPAREN)) {
        for_stmt->step = parse_expr(p);
    }
    consume(p, TK_RPAREN, "Expected )");

    for_stmt->body = parse_statement(p);

    return for_stmt;
}

/* return 문 파싱 */
Node *parse_return_statement(Parser *p) {
    Token tok = *current_token(p);
    consume(p, TK_RETURN, "Expected return");

    Node *return_stmt = node_new(ND_RETURN, tok.loc);

    if (!check(p, TK_SEMICOLON)) {
        return_stmt->left = parse_expr(p);
    }

    consume(p, TK_SEMICOLON, "Expected ;");
    return return_stmt;
}

/* 식 파싱 (최상위) */
Node *parse_expr(Parser *p) {
    return parse_assign_expr(p);
}

/* 할당 식 파싱 */
Node *parse_assign_expr(Parser *p) {
    Node *left = parse_ternary_expr(p);
    if (!left) return NULL;

    if (check(p, TK_ASSIGN) || check(p, TK_PLUS_ASSIGN) ||
        check(p, TK_MINUS_ASSIGN) || check(p, TK_STAR_ASSIGN) ||
        check(p, TK_SLASH_ASSIGN) || check(p, TK_PERCENT_ASSIGN)) {

        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);

        Node *assign = node_new(ND_ASSIGN, op_tok.loc);
        assign->op = op;
        assign->left = left;
        assign->right = parse_assign_expr(p);

        return assign;
    }

    return left;
}

/* 삼항 식 파싱 */
Node *parse_ternary_expr(Parser *p) {
    Node *expr = parse_logical_or_expr(p);
    if (!expr) return NULL;

    if (match(p, TK_QUESTION)) {
        Token tok = expr->loc;
        Node *ternary = node_new(ND_TERNARY, tok);
        ternary->cond = expr;
        ternary->left = parse_expr(p);
        consume(p, TK_COLON, "Expected :");
        ternary->right = parse_ternary_expr(p);
        return ternary;
    }

    return expr;
}

/* 논리 OR 파싱 */
Node *parse_logical_or_expr(Parser *p) {
    Node *left = parse_logical_and_expr(p);
    if (!left) return NULL;

    while (check(p, TK_OR)) {
        Token op_tok = *current_token(p);
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = TK_OR;
        binary->left = left;
        binary->right = parse_logical_and_expr(p);
        left = binary;
    }

    return left;
}

/* 논리 AND 파싱 */
Node *parse_logical_and_expr(Parser *p) {
    Node *left = parse_bitwise_or_expr(p);
    if (!left) return NULL;

    while (check(p, TK_AND)) {
        Token op_tok = *current_token(p);
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = TK_AND;
        binary->left = left;
        binary->right = parse_bitwise_or_expr(p);
        left = binary;
    }

    return left;
}

/* 비트 OR 파싱 */
Node *parse_bitwise_or_expr(Parser *p) {
    Node *left = parse_bitwise_xor_expr(p);
    if (!left) return NULL;

    while (check(p, TK_PIPE)) {
        Token op_tok = *current_token(p);
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = TK_PIPE;
        binary->left = left;
        binary->right = parse_bitwise_xor_expr(p);
        left = binary;
    }

    return left;
}

/* 비트 XOR 파싱 */
Node *parse_bitwise_xor_expr(Parser *p) {
    Node *left = parse_bitwise_and_expr(p);
    if (!left) return NULL;

    while (check(p, TK_CARET)) {
        Token op_tok = *current_token(p);
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = TK_CARET;
        binary->left = left;
        binary->right = parse_bitwise_and_expr(p);
        left = binary;
    }

    return left;
}

/* 비트 AND 파싱 */
Node *parse_bitwise_and_expr(Parser *p) {
    Node *left = parse_equality_expr(p);
    if (!left) return NULL;

    while (check(p, TK_AMPERSAND)) {
        Token op_tok = *current_token(p);
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = TK_AMPERSAND;
        binary->left = left;
        binary->right = parse_equality_expr(p);
        left = binary;
    }

    return left;
}

/* 동치 파싱 */
Node *parse_equality_expr(Parser *p) {
    Node *left = parse_relational_expr(p);
    if (!left) return NULL;

    while (check(p, TK_EQ) || check(p, TK_NEQ)) {
        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = op;
        binary->left = left;
        binary->right = parse_relational_expr(p);
        left = binary;
    }

    return left;
}

/* 관계 파싱 */
Node *parse_relational_expr(Parser *p) {
    Node *left = parse_shift_expr(p);
    if (!left) return NULL;

    while (check(p, TK_LT) || check(p, TK_LE) || check(p, TK_GT) || check(p, TK_GE)) {
        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = op;
        binary->left = left;
        binary->right = parse_shift_expr(p);
        left = binary;
    }

    return left;
}

/* 시프트 파싱 */
Node *parse_shift_expr(Parser *p) {
    Node *left = parse_additive_expr(p);
    if (!left) return NULL;

    while (check(p, TK_LSHIFT) || check(p, TK_RSHIFT)) {
        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = op;
        binary->left = left;
        binary->right = parse_additive_expr(p);
        left = binary;
    }

    return left;
}

/* 더하기/빼기 파싱 */
Node *parse_additive_expr(Parser *p) {
    Node *left = parse_multiplicative_expr(p);
    if (!left) return NULL;

    while (check(p, TK_PLUS) || check(p, TK_MINUS)) {
        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = op;
        binary->left = left;
        binary->right = parse_multiplicative_expr(p);
        left = binary;
    }

    return left;
}

/* 곱하기/나누기 파싱 */
Node *parse_multiplicative_expr(Parser *p) {
    Node *left = parse_unary_expr(p);
    if (!left) return NULL;

    while (check(p, TK_STAR) || check(p, TK_SLASH) || check(p, TK_PERCENT)) {
        Token op_tok = *current_token(p);
        TokenKind op = op_tok.kind;
        advance(p);
        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->op = op;
        binary->left = left;
        binary->right = parse_unary_expr(p);
        left = binary;
    }

    return left;
}

/* 단항 식 파싱 */
Node *parse_unary_expr(Parser *p) {
    Token tok = *current_token(p);

    if (match(p, TK_BANG)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_BANG;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_TILDE)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_TILDE;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_MINUS)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_MINUS;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_PLUS)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_PLUS;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_INC)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_INC;
        unary->is_prefix = 1;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_DEC)) {
        Node *unary = node_new(ND_UNARY, tok.loc);
        unary->op = TK_DEC;
        unary->is_prefix = 1;
        unary->left = parse_unary_expr(p);
        return unary;
    } else if (match(p, TK_SIZEOF)) {
        if (check(p, TK_LPAREN)) {
            /* sizeof(type) */
            advance(p);
            Node *sizeof_type = node_new(ND_SIZEOF_TYPE, tok.loc);
            sizeof_type->type_node = parse_type(p);
            consume(p, TK_RPAREN, "Expected )");
            return sizeof_type;
        } else {
            /* sizeof expr */
            Node *sizeof_expr = node_new(ND_SIZEOF_EXPR, tok.loc);
            sizeof_expr->left = parse_unary_expr(p);
            return sizeof_expr;
        }
    }

    return parse_postfix_expr(p);
}

/* 후위 식 파싱 */
Node *parse_postfix_expr(Parser *p) {
    Node *expr = parse_primary_expr(p);
    if (!expr) return NULL;

    while (1) {
        if (check(p, TK_LBRACKET)) {
            /* 배열 인덱싱 */
            Token tok = *current_token(p);
            advance(p);
            Node *index = node_new(ND_INDEX, tok.loc);
            index->left = expr;
            index->right = parse_expr(p);
            consume(p, TK_RBRACKET, "Expected ]");
            expr = index;
        } else if (check(p, TK_LPAREN)) {
            /* 함수 호출 */
            Token tok = *current_token(p);
            advance(p);
            Node *call = node_new(ND_CALL, tok.loc);
            call->left = expr;

            while (!check(p, TK_RPAREN)) {
                Node *arg = parse_assign_expr(p);
                if (arg) {
                    node_add_child(call, arg);
                }
                if (!match(p, TK_COMMA)) break;
            }

            consume(p, TK_RPAREN, "Expected )");
            expr = call;
        } else if (match(p, TK_INC)) {
            /* 후위 ++ */
            Node *unary = node_new(ND_UNARY, expr->loc);
            unary->op = TK_INC;
            unary->is_prefix = 0;
            unary->left = expr;
            expr = unary;
        } else if (match(p, TK_DEC)) {
            /* 후위 -- */
            Node *unary = node_new(ND_UNARY, expr->loc);
            unary->op = TK_DEC;
            unary->is_prefix = 0;
            unary->left = expr;
            expr = unary;
        } else if (match(p, TK_DOT)) {
            /* 멤버 접근 */
            Token tok = expr->loc;
            Node *member = node_new(ND_MEMBER, tok);
            member->left = expr;
            if (check(p, TK_IDENT)) {
                member->name = (char *)malloc(strlen(current_token(p)->val.ident) + 1);
                strcpy(member->name, current_token(p)->val.ident);
                advance(p);
            }
            expr = member;
        } else if (match(p, TK_ARROW)) {
            /* 포인터 멤버 접근 (Phase 3.1) */
            Token tok = expr->loc;
            Node *arrow = node_new(ND_ARROW, tok);
            arrow->left = expr;
            if (check(p, TK_IDENT)) {
                arrow->name = (char *)malloc(strlen(current_token(p)->val.ident) + 1);
                strcpy(arrow->name, current_token(p)->val.ident);
                advance(p);
            }
            expr = arrow;
        } else {
            break;
        }
    }

    return expr;
}

/* 기본 식 파싱 */
Node *parse_primary_expr(Parser *p) {
    Token tok = *current_token(p);

    /* 리터럴 */
    if (check(p, TK_INT_LIT)) {
        Node *lit = node_new(ND_INT_LIT, tok.loc);
        lit->int_val = tok.val.int_val;
        advance(p);
        return lit;
    } else if (check(p, TK_FLOAT_LIT)) {
