#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../../src/lexer.h"
#include "../../src/parser.h"
#include "../../src/ast.h"
#include "../test_framework.h"

/* 헬퍼 함수 */
static Node *parse_string(const char *code) {
    Lexer *lexer = lexer_new(code, strlen(code));
    if (!lexer) return NULL;

    lexer_tokenize(lexer);

    Parser *parser = parser_new(lexer);
    if (!parser) {
        lexer_free(lexer);
        return NULL;
    }

    Node *ast = parse_program(parser);
    parser_free(parser);
    lexer_free(lexer);
    return ast;
}

static int node_is_kind(Node *node, NodeKind kind) {
    return node != NULL && node->kind == kind;
}

static int node_is_int_lit(Node *node, long long val) {
    return node != NULL && node->kind == ND_INT_LIT && node->int_val == val;
}

/* 테스트: 정수 리터럴 */
TEST(test_parse_int_literal) {
    Node *ast = parse_string("{ 42; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 식별자 */
TEST(test_parse_identifier) {
    Node *ast = parse_string("{ x; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 덧셈 */
TEST(test_parse_addition) {
    Node *ast = parse_string("{ a + b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 뺄셈 */
TEST(test_parse_subtraction) {
    Node *ast = parse_string("{ x - y; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 곱셈 */
TEST(test_parse_multiplication) {
    Node *ast = parse_string("{ a * b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 나눗셈 */
TEST(test_parse_division) {
    Node *ast = parse_string("{ x / y; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 나머지 */
TEST(test_parse_modulo) {
    Node *ast = parse_string("{ a % b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 연산자 우선순위 (곱셈이 덧셈보다 먼저) */
TEST(test_parse_precedence_mult_add) {
    Node *ast = parse_string("{ 2 + 3 * 4; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 연산자 우선순위 (괄호) */
TEST(test_parse_precedence_parentheses) {
    Node *ast = parse_string("{ (2 + 3) * 4; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 비교 연산자 (==) */
TEST(test_parse_equality_eq) {
    Node *ast = parse_string("{ a == b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 비교 연산자 (!=) */
TEST(test_parse_equality_neq) {
    Node *ast = parse_string("{ x != y; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 관계 연산자 (<) */
TEST(test_parse_relational_lt) {
    Node *ast = parse_string("{ a < b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 관계 연산자 (>) */
TEST(test_parse_relational_gt) {
    Node *ast = parse_string("{ x > y; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 관계 연산자 (<=) */
TEST(test_parse_relational_le) {
    Node *ast = parse_string("{ a <= b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 관계 연산자 (>=) */
TEST(test_parse_relational_ge) {
    Node *ast = parse_string("{ x >= y; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 논리 AND (&&) */
TEST(test_parse_logical_and) {
    Node *ast = parse_string("{ a && b; }");
    ASSERT(node_is_kind(ast, ND_PROGRAM));
    ASSERT(ast->child_count > 0);
}

/* 테스트: 논리 OR (||) */
TEST(test_parse_logical_or) {
