TEST(test_ir_astgen_lifecycle) {
    CirModule *m = cir_module_new();
    ASSERT(m != NULL);
    AstGen *g = astgen_new(m);
    ASSERT(g != NULL);
    astgen_free(g);
    cir_module_free(m);
}

