    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; if (x) { } }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_if_else_stmt) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; if (x) { } else { } }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_while_stmt) {
    Sema *s = sema_new();
