    RUN_TEST(test_sema_binary_add, &count, &passed, &failed);
    RUN_TEST(test_sema_binary_eq, &count, &passed, &failed);

    /* Control Flow */
    RUN_TEST(test_sema_if_stmt, &count, &passed, &failed);
    RUN_TEST(test_sema_if_else_stmt, &count, &passed, &failed);
    RUN_TEST(test_sema_while_stmt, &count, &passed, &failed);
    RUN_TEST(test_sema_for_stmt, &count, &passed, &failed);
