    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_check_string_lit) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { \"hello\"; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

/* Test: variable declaration */
TEST(test_sema_var_decl) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; }");
    ASSERT(program != NULL);
