    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_undefined_var) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { x = 5; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count > 0);  /* 미선언 변수 에러 */
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_var_use) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; x = 5; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

/* Test: function */
TEST(test_sema_func_def_void) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_func_def_int) {
    Sema *s = sema_new();
    Node *program = program_from_string("int f() { return 42; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_return_type_match) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { return; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_undefined_func_call) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { g(); }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count > 0);  /* 미정의 함수 */
    ast_free(program);
    sema_free(s);
}

/* Test: binary operations */
TEST(test_sema_binary_add) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; int y; x + y; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

TEST(test_sema_binary_eq) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { int x; int y; x == y; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    ast_free(program);
    sema_free(s);
}

