#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../test_framework.h"
#include "../../src/lexer.h"
#include "../../src/parser.h"
#include "../../src/sema.h"

/* Helper: create program from C code string */
Node *program_from_string(const char *code) {
    Lexer *lex = lexer_new(code, strlen(code));
    if (!lex) return NULL;
    if (lexer_tokenize(lex) != 0) { lexer_free(lex); return NULL; }
    Parser *p = parser_new(lex);
    if (!p) { lexer_free(lex); return NULL; }
    Node *program = parse_program(p);
    parser_free(p);
    lexer_free(lex);
    return program;
}

/* Test: basic type creation */
TEST(test_sema_type_basic_int) {
    SemaType *t = sema_type_basic(SEMA_TYPE_INT);
    ASSERT(t != NULL);
    ASSERT(t->kind == SEMA_TYPE_INT);
    sema_type_free(t);
}

TEST(test_sema_type_basic_void) {
    SemaType *t = sema_type_basic(SEMA_TYPE_VOID);
    ASSERT(t != NULL);
    ASSERT(t->kind == SEMA_TYPE_VOID);
    sema_type_free(t);
}

TEST(test_sema_type_ptr) {
    SemaType *base = sema_type_basic(SEMA_TYPE_INT);
    SemaType *ptr = sema_type_ptr(base);
    ASSERT(ptr != NULL);
    ASSERT(ptr->kind == SEMA_TYPE_PTR);
    ASSERT(ptr->base->kind == SEMA_TYPE_INT);
    sema_type_free(ptr);
}

TEST(test_sema_type_array) {
    SemaType *base = sema_type_basic(SEMA_TYPE_INT);
    SemaType *arr = sema_type_array(base, 10);
    ASSERT(arr != NULL);
    ASSERT(arr->kind == SEMA_TYPE_ARRAY);
    ASSERT(arr->array_size == 10);
    sema_type_free(arr);
}

TEST(test_sema_types_compatible_int_char) {
    SemaType *t1 = sema_type_basic(SEMA_TYPE_INT);
    SemaType *t2 = sema_type_basic(SEMA_TYPE_CHAR);
    ASSERT(sema_types_compatible(t1, t2) == 1);
    sema_type_free(t1);
    sema_type_free(t2);
}

/* Test: symbol table */
TEST(test_sema_symtable_define_lookup) {
    SymTable *t = symtable_new();
    ASSERT(t != NULL);
    SemaType *int_type = sema_type_basic(SEMA_TYPE_INT);
    Symbol *sym = symtable_define(t, "x", SYM_VAR, int_type);
    ASSERT(sym != NULL);
    Symbol *found = symtable_lookup(t, "x");
    ASSERT(found != NULL);
    ASSERT(strcmp(found->name, "x") == 0);
    symtable_free(t);
}

TEST(test_sema_symtable_not_found) {
    SymTable *t = symtable_new();
    ASSERT(t != NULL);
    Symbol *found = symtable_lookup(t, "undefined");
    ASSERT(found == NULL);
    symtable_free(t);
}

TEST(test_sema_symtable_duplicate) {
    SymTable *t = symtable_new();
    ASSERT(t != NULL);
    SemaType *int_type = sema_type_basic(SEMA_TYPE_INT);
    Symbol *sym1 = symtable_define(t, "x", SYM_VAR, int_type);
    ASSERT(sym1 != NULL);
    Symbol *sym2 = symtable_define(t, "x", SYM_VAR, int_type);
    ASSERT(sym2 == NULL);  /* 중복 → NULL */
    symtable_free(t);
}

TEST(test_sema_symtable_scope) {
    SymTable *t = symtable_new();
    ASSERT(t != NULL);
    SemaType *int_type = sema_type_basic(SEMA_TYPE_INT);
    Symbol *sym1 = symtable_define(t, "x", SYM_VAR, int_type);
    ASSERT(sym1 != NULL);
    symtable_enter_scope(t);
    Symbol *found_in_inner = symtable_lookup(t, "x");
    ASSERT(found_in_inner != NULL);  /* 상위 스코프에서 찾음 */
    symtable_exit_scope(t);
    symtable_free(t);
}

/* Test: Sema creation */
TEST(test_sema_new_free) {
    Sema *s = sema_new();
    ASSERT(s != NULL);
    ASSERT(s->syms != NULL);
    ASSERT(s->loop_depth == 0);
    ASSERT(s->error_count == 0);
    sema_free(s);
}

/* Test: type inference from literals */
TEST(test_sema_check_int_lit) {
    Sema *s = sema_new();
    Node *program = program_from_string("void f() { 42; }");
    ASSERT(program != NULL);
    sema_check(s, program);
    ASSERT(s->error_count == 0);
    node_free_recursive(program);
    sema_free(s);
}

