    88→/* AstGen (AST → CIR converter state) */
    89→typedef struct {
    90→    CirModule *module;
    91→
    92→    /* Local variable name → str_idx mapping */
    93→    char     **var_names;
    94→    uint32_t  *var_ids;
    95→    int        var_count;
    96→    int        var_cap;
    97→
    98→    /* break/continue labels */
