/* C Self-Hosting Compiler - Main Driver */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lexer.h"
#include "parser.h"
#include "ir.h"
#include "sema.h"
#include "codegen.h"

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.c> [output.s]\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = (argc >= 3) ? argv[2] : "output.s";

    /* Phase 1: Read source file */
    FILE *fin = fopen(input_file, "r");
    if (!fin) {
        fprintf(stderr, "Error: Cannot open input file '%s'\n", input_file);
        return 1;
    }

    fseek(fin, 0, SEEK_END);
    long fsize = ftell(fin);
    fseek(fin, 0, SEEK_SET);

    char *source = (char *)malloc(fsize + 1);
    if (!source) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(fin);
        return 1;
    }

    size_t read_size = fread(source, 1, fsize, fin);
    source[read_size] = '\0';
    fclose(fin);

    /* Phase 2: Lexer */
    Lexer *lexer = lexer_new(source);
    if (!lexer) {
        fprintf(stderr, "Error: Lexer initialization failed\n");
        free(source);
        return 1;
    }

    /* Phase 3: Parser */
    Parser *parser = parser_new(lexer);
    if (!parser) {
        fprintf(stderr, "Error: Parser initialization failed\n");
        lexer_free(lexer);
        free(source);
        return 1;
    }

    AstProgram *program = parser_parse(parser);
    if (!program) {
        fprintf(stderr, "Error: Parse failed\n");
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    /* Phase 4: IR Generation (AST -> CIR) */
    CirModule *ir = cir_module_new();
    if (!ir) {
        fprintf(stderr, "Error: IR module creation failed\n");
        ast_program_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    AstGen astgen = {0};
    astgen.module = ir;
    if (!astgen_program(&astgen, program)) {
        fprintf(stderr, "Error: IR generation failed\n");
        cir_module_free(ir);
        ast_program_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    /* Phase 5: Semantic Analysis */
    Sema sema = {0};
    sema.module = ir;
    if (!sema_analyze(&sema, program)) {
        fprintf(stderr, "Error: Semantic analysis failed\n");
        cir_module_free(ir);
        ast_program_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    /* Phase 6: Code Generation (CIR -> x86-64 Assembly) */
    FILE *fout = fopen(output_file, "w");
    if (!fout) {
        fprintf(stderr, "Error: Cannot open output file '%s'\n", output_file);
        cir_module_free(ir);
        ast_program_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    Codegen *codegen = codegen_new(ir, fout);
    if (!codegen) {
        fprintf(stderr, "Error: Codegen initialization failed\n");
        fclose(fout);
        cir_module_free(ir);
        ast_program_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    codegen_emit(codegen);

    codegen_free(codegen);
    fclose(fout);

    /* Cleanup */
    cir_module_free(ir);
    ast_program_free(program);
    parser_free(parser);
    lexer_free(lexer);
    free(source);

    fprintf(stderr, "Compilation successful: %s -> %s\n", input_file, output_file);
    return 0;
}

