#ifndef SEMA_H
#define SEMA_H

#include <stdint.h>
#include "ast.h"

/* Type system */
typedef enum {
    SEMA_TYPE_VOID,
    SEMA_TYPE_CHAR,
    SEMA_TYPE_INT,
    SEMA_TYPE_FLOAT,
    SEMA_TYPE_DOUBLE,
    SEMA_TYPE_LONG,
    SEMA_TYPE_PTR,
    SEMA_TYPE_ARRAY,
    SEMA_TYPE_FUNC,
    SEMA_TYPE_STRUCT,
    SEMA_TYPE_UNKNOWN,
} SemaTypeKind;

typedef struct SemaType {
    SemaTypeKind kind;
    struct SemaType *base;       /* PTR, ARRAY → 원소 타입 */
    int array_size;              /* ARRAY 크기 */
    int is_const;
} SemaType;

/* Symbol table */
typedef enum { SYM_VAR, SYM_FUNC, SYM_TYPE } SymKind;

typedef struct Symbol {
    char           *name;
    SymKind         kind;
    SemaType       *type;        /* 변수 타입, 함수 반환 타입 */
    int             param_count; /* 함수 매개변수 개수 */
    struct Symbol  *next;        /* 해시 체인 */
} Symbol;

typedef struct Scope {
    Symbol      **syms;
    int           sym_count;
    int           sym_cap;
    struct Scope *parent;        /* NULL = 전역 스코프 */
} Scope;

typedef struct {
    Scope *current;
    Scope *global;
} SymTable;

/* Sema (Semantic Analysis state) */
typedef struct {
    SymTable   *syms;

    SemaType   *current_func_ret;   /* 현재 함수 반환 타입 */
    int         loop_depth;          /* break/continue 검증 */
    int         error_count;
} Sema;

/* Type operations */
SemaType  *sema_type_basic(SemaTypeKind kind);
SemaType  *sema_type_ptr(SemaType *base);
SemaType  *sema_type_array(SemaType *base, int size);
void       sema_type_free(SemaType *t);
int        sema_types_compatible(SemaType *a, SemaType *b);
const char *sema_type_to_string(SemaType *t);

/* Symbol table operations */
SymTable  *symtable_new(void);
void       symtable_free(SymTable *t);
void       symtable_enter_scope(SymTable *t);
void       symtable_exit_scope(SymTable *t);
Symbol    *symtable_define(SymTable *t, const char *name, SymKind kind, SemaType *type);
Symbol    *symtable_lookup(SymTable *t, const char *name);

/* Sema operations */
Sema      *sema_new(void);
void       sema_free(Sema *s);
int        sema_check(Sema *s, Node *program);    /* 에러 수 반환 */
SemaType  *sema_check_expr(Sema *s, Node *expr);  /* 식의 타입 반환 */
int        sema_check_stmt(Sema *s, Node *stmt);
int        sema_check_decl(Sema *s, Node *decl);

#endif /* SEMA_H */

#ifndef CODEGEN_H
#define CODEGEN_H

#include <stdio.h>
#include "ir.h"

/* Codegen (Code Generation) state */
typedef struct {
    FILE       *out;           /* 어셈블리 출력 파일 */
    CirModule  *module;        /* 입력 CIR 모듈 */

    /* CirRef → rbp 오프셋 맵 */
    int        *ref_offsets;   /* CirRef → 스택 오프셋 (음수, -8부터) */
    int         ref_count;     /* 할당된 ref 슬롯 수 */

    /* 변수명 → 스택 오프셋 맵 */
    uint32_t   *var_name_idx;  /* 변수 name_idx 배열 */
    int        *var_offsets;   /* 각 변수의 rbp 오프셋 */
    int         var_count;
    int         var_cap;

    /* 함수 범위 */
    uint32_t    func_start;    /* CIR_FUNC_BEGIN 인덱스 */
    uint32_t    func_end;      /* CIR_FUNC_END 인덱스 */
    int         stack_size;    /* 현재 함수 스택 크기 (16바이트 정렬) */
} Codegen;

/* 초기화/해제 */
Codegen  *codegen_new(CirModule *m, FILE *out);
void      codegen_free(Codegen *cg);

/* 생성 진입점 */
void      codegen_emit(Codegen *cg);    /* 전체 프로그램 어셈블리 생성 */

#endif /* CODEGEN_H */

