/* C Self-Hosting Compiler - Main Driver */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lexer.h"
#include "parser.h"
#include "ir.h"
#include "sema.h"
#include "codegen.h"

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.c> [output.s]\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = (argc >= 3) ? argv[2] : "output.s";

    /* Phase 1: Read source file */
    FILE *fin = fopen(input_file, "r");
    if (!fin) {
        fprintf(stderr, "Error: Cannot open input file '%s'\n", input_file);
        return 1;
    }

    fseek(fin, 0, SEEK_END);
    long fsize = ftell(fin);
    fseek(fin, 0, SEEK_SET);

    char *source = (char *)malloc(fsize + 1);
    if (!source) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(fin);
        return 1;
    }

    size_t read_size = fread(source, 1, fsize, fin);
    source[read_size] = '\0';
    fclose(fin);

    /* Phase 2: Lexer */
    Lexer *lexer = lexer_new(source, read_size);
    if (!lexer) {
        fprintf(stderr, "Error: Lexer initialization failed\n");
        free(source);
        return 1;
    }

    fprintf(stderr, "[DEBUG] Tokenizing...\n");
    if (lexer_tokenize(lexer) != 0) {
        fprintf(stderr, "Error: Tokenization failed\n");
        lexer_free(lexer);
        free(source);
        return 1;
    }
    fprintf(stderr, "[DEBUG] Tokenization complete: %zu tokens\n", lexer->tok_count);

    /* Phase 3: Parser */
    fprintf(stderr, "[DEBUG] Creating parser...\n");
    Parser *parser = parser_new(lexer);
    if (!parser) {
        fprintf(stderr, "Error: Parser initialization failed\n");
        lexer_free(lexer);
        free(source);
        return 1;
    }
    fprintf(stderr, "[DEBUG] Parser created, parsing program...\n");

    Node *program = parse_program(parser);
    fprintf(stderr, "[DEBUG] Parse returned: %p\n", (void*)program);
    if (!program) {
        fprintf(stderr, "Error: Parse failed\n");
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }
    fprintf(stderr, "[DEBUG] Program parsed successfully\n");

    /* Phase 4: IR Generation (AST -> CIR) */
    fprintf(stderr, "[DEBUG] Creating IR module...\n");
    CirModule *ir = cir_module_new();
    if (!ir) {
        fprintf(stderr, "Error: IR module creation failed\n");
        node_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    fprintf(stderr, "[DEBUG] Running AstGen...\n");
    AstGen astgen = {0};
    astgen.module = ir;
    astgen_program(&astgen, program);
    fprintf(stderr, "[DEBUG] AstGen complete: %u instructions\n", ir->inst_count);

    /* Phase 5: Semantic Analysis */
    fprintf(stderr, "[DEBUG] Creating Sema...\n");
    Sema *sema = sema_new();
    if (!sema) {
        fprintf(stderr, "Error: Sema initialization failed\n");
        cir_module_free(ir);
        node_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    fprintf(stderr, "[DEBUG] Running semantic analysis...\n");
    int sema_errors = sema_check(sema, program);
    fprintf(stderr, "[DEBUG] Sema complete: %d errors\n", sema_errors);

    if (sema_errors > 0) {
        fprintf(stderr, "Error: Semantic analysis found %d errors\n", sema_errors);
        sema_free(sema);
        cir_module_free(ir);
        node_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    /* Phase 6: Code Generation (CIR -> x86-64 Assembly) */
    fprintf(stderr, "[DEBUG] Opening output file: %s\n", output_file);
    FILE *fout = fopen(output_file, "w");
    if (!fout) {
        fprintf(stderr, "Error: Cannot open output file '%s'\n", output_file);
        sema_free(sema);
        cir_module_free(ir);
        node_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    fprintf(stderr, "[DEBUG] Creating Codegen...\n");
    Codegen *codegen = codegen_new(ir, fout);
    if (!codegen) {
        fprintf(stderr, "Error: Codegen initialization failed\n");
        fclose(fout);
        sema_free(sema);
        cir_module_free(ir);
        node_free(program);
        parser_free(parser);
        lexer_free(lexer);
        free(source);
        return 1;
    }

    fprintf(stderr, "[DEBUG] Emitting code...\n");
    codegen_emit(codegen);
    fprintf(stderr, "[DEBUG] Code emission complete\n");

    codegen_free(codegen);
    fclose(fout);

    /* Cleanup */
    sema_free(sema);
    cir_module_free(ir);
    node_free(program);
    parser_free(parser);
    lexer_free(lexer);
    free(source);

    fprintf(stderr, "Compilation successful: %s -> %s\n", input_file, output_file);
    return 0;
}

