    15→    Node *program = parse_program(p);
    16→    parser_free(p);
    17→    lexer_free(lex);
    18→    if (!program) return NULL;
    19→    
    20→    CirModule *m = cir_module_new();
    21→    AstGen *g = astgen_new(m);
    22→    astgen_program(g, program);
    23→    astgen_free(g);
    24→    node_free_recursive(program);
    25→    return m;
    26→}
