   111→/* Main codegen: instruction processing */
   112→static void codegen_inst(Codegen *cg, uint32_t ref) {
   113→    if (ref >= cg->module->inst_count) return;
   114→    CirInst *inst = &cg->module->insts[ref];
   115→
   116→    switch (inst->op) {
   117→        case CIR_LOAD_INT: {
   118→            int slot = alloc_ref_offset(cg);
   119→            fprintf(cg->out, "    movq    $%lld, %d(%%rbp)\n",
   120→                    inst->u.load_int.imm, cg->ref_offsets[slot]);
   121→            break;
   122→        }
   123→        case CIR_LOAD_FLOAT: {
   124→            int slot = alloc_ref_offset(cg);
   125→            fprintf(cg->out, "    movsd   .LC_FLOAT_%u(%%rip), %%xmm0\n", ref);
   126→            fprintf(cg->out, "    movsd   %%xmm0, %d(%%rbp)\n", cg->ref_offsets[slot]);
   127→            break;
   128→        }
   129→        case CIR_LOAD_STR: {
   130→            int slot = alloc_ref_offset(cg);
   131→            fprintf(cg->out, "    leaq    .LC%u(%%rip), %%rax\n",
   132→                    inst->u.load_str.str_idx);
   133→            fprintf(cg->out, "    movq    %%rax, %d(%%rbp)\n", cg->ref_offsets[slot]);
   134→            break;
   135→        }
   136→        case CIR_LOAD_VAR: {
   137→            int slot = alloc_ref_offset(cg);
   138→            int var_offset = get_var_offset(cg, inst->u.load_var.name_idx);
   139→            fprintf(cg->out, "    movq    %d(%%rbp), %%rax\n", var_offset);
   140→            fprintf(cg->out, "    movq    %%rax, %d(%%rbp)\n", cg->ref_offsets[slot]);
   141→            break;
   142→        }
   143→        case CIR_STORE_VAR: {
   144→            int var_offset = get_var_offset(cg, inst->u.store_var.name_idx);
   145→            CirRef val_ref = inst->u.store_var.value;
   146→            if (val_ref < cg->ref_count) {
   147→                fprintf(cg->out, "    movq    %d(%%rbp), %%rax\n", cg->ref_offsets[val_ref]);
   148→                fprintf(cg->out, "    movq    %%rax, %d(%%rbp)\n", var_offset);
   149→            }
   150→            break;
   151→        }
   152→        case CIR_BINARY: {
   153→            int slot = alloc_ref_offset(cg);
   154→            CirRef lhs = inst->u.binary.lhs;
   155→            CirRef rhs = inst->u.binary.rhs;
   156→            int op = inst->u.binary.op;
   157→
   158→            if (lhs >= cg->ref_count || rhs >= cg->ref_count) break;
   159→
   160→            fprintf(cg->out, "    movq    %d(%%rbp), %%rax\n", cg->ref_offsets[lhs]);
   161→            fprintf(cg->out, "    movq    %d(%%rbp), %%rbx\n", cg->ref_offsets[rhs]);
   162→
   163→            switch (op) {
   164→                case 0:  /* ADD */ fprintf(cg->out, "    addq    %%rbx, %%rax\n"); break;
   165→                case 1:  /* SUB */ fprintf(cg->out, "    subq    %%rbx, %%rax\n"); break;
   166→                case 2:  /* MUL */ fprintf(cg->out, "    imulq   %%rbx, %%rax\n"); break;
   167→                case 3:  /* DIV */
   168→                    fprintf(cg->out, "    cqo\n");
   169→                    fprintf(cg->out, "    idivq   %%rbx\n");
   170→                    break;
   171→                case 4:  /* MOD */
   172→                    fprintf(cg->out, "    cqo\n");
   173→                    fprintf(cg->out, "    idivq   %%rbx\n");
   174→                    fprintf(cg->out, "    movq    %%rdx, %%rax\n");
   175→                    break;
   176→                case 6:  /* LE */
   177→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   178→                    fprintf(cg->out, "    setle   %%al\n");
   179→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   180→                    break;
   181→                case 7:  /* GT */
   182→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   183→                    fprintf(cg->out, "    setg    %%al\n");
   184→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   185→                    break;
   186→                case 8:  /* GE */
   187→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   188→                    fprintf(cg->out, "    setge   %%al\n");
   189→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   190→                    break;
   191→                case 12: /* EQ */
   192→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   193→                    fprintf(cg->out, "    sete    %%al\n");
   194→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   195→                    break;
   196→                case 13: /* NEQ */
   197→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   198→                    fprintf(cg->out, "    setne   %%al\n");
   199→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   200→                    break;
   201→                case 14: /* LT */
   202→                    fprintf(cg->out, "    cmpq    %%rbx, %%rax\n");
   203→                    fprintf(cg->out, "    setl    %%al\n");
   204→                    fprintf(cg->out, "    movzbq  %%al, %%rax\n");
   205→                    break;
   206→                case 9:  /* AND */ fprintf(cg->out, "    andq    %%rbx, %%rax\n"); break;
   207→                case 10: /* OR  */ fprintf(cg->out, "    orq     %%rbx, %%rax\n"); break;
   208→                case 11: /* XOR */ fprintf(cg->out, "    xorq    %%rbx, %%rax\n"); break;
   209→                case 15: /* LSHIFT */ fprintf(cg->out, "    shlq    %%cl, %%rax\n"); break;
   210→                case 16: /* RSHIFT */ fprintf(cg->out, "    sarq    %%cl, %%rax\n"); break;
   211→                case 18: /* LOGIC_AND */
